const body = $json.body || $json;

const get = (keys, d = '') => {
  for (const k of keys) {
    if (body[k] !== undefined && body[k] !== null && body[k] !== '') return body[k];
  }
  return d;
};

return [{
  json: {
    form_triggered: true,
    source: 'google_forms',
    search_name: get(['search_name', 'Search Name', 'searchName'], `form_run_${Date.now()}`),
    company_list: get(['company_list', 'Company List', 'companyList'], ''),
    job_titles: get(['job_titles', 'Job Titles', 'jobTitles'], ''),
    locations: get(['locations', 'Locations'], 'India'),
    industry_ids: get(['industry_ids', 'Industry IDs', 'industryIds'], ''),
    employment_type: get(['employment_type', 'Employment Type', 'employmentType'], 'full-time'),
    experience_levels: get(['experience_levels', 'Experience Levels', 'experienceLevels'], 'entry,associate,mid-senior'),
    workplace_types: get(['workplace_types', 'Workplace Types', 'workplaceTypes'], 'hybrid,remote,office'),
    easy_apply: get(['easy_apply', 'Easy Apply', 'easyApply'], 'false'),
    under_10_applicants: get(['under_10_applicants', 'Under 10 Applicants', 'under10Applicants'], 'false'),
    max_items: get(['max_items', 'Max Items', 'maxItems'], '25'),
    country_filter: get(['country_filter', 'Country Filter', 'countryFilter'], 'IN')
  }
}];

const incoming = $json;
const now = new Date();
const runId = `run_${now.toISOString().replace(/[-:.TZ]/g, '').slice(0, 14)}_${$execution.id}`;

return [{
  json: {
    ...incoming,
    run_id: runId,
    started_at: now.toISOString(),
    completed_at: '',
    jobs_scraped: 0,
    jobs_filtered: 0,
    jobs_added: 0,
    jobs_rejected: 0,
    ai_processed: 0,
    failures: 0,
    notes: 'started_from_google_form'
  }
}];

const parseBool = (v, d = false) => {
  if (v === undefined || v === null || v === '') return d;
  if (typeof v === 'boolean') return v;
  return String(v).trim().toLowerCase() === 'true';
};

const parseIntSafe = (v, d = 25) => {
  const n = Number(v);
  return Number.isFinite(n) && n > 0 ? n : d;
};

const parseCsv = (v) => {
  if (!v) return [];
  return String(v)
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
};

return $input.all().map((item) => {
  const f = item.json;

  const config = {
    search_name: f.search_name || `form_${new Date().toISOString().slice(0, 10)}`,
    company_list: parseCsv(f.company_list),
    job_titles: parseCsv(f.job_titles),
    locations: parseCsv(f.locations),
    industry_ids: parseCsv(f.industry_ids),
    employment_type: parseCsv(f.employment_type),
    experience_levels: parseCsv(f.experience_levels),
    workplace_types: parseCsv(f.workplace_types),
    easy_apply: parseBool(f.easy_apply, false),
    under_10_applicants: parseBool(f.under_10_applicants, false),
    max_items: parseIntSafe(f.max_items, 25),
    country_filter: (f.country_filter || 'IN').toUpperCase(),
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  };

  const payload = {
    company: config.company_list,
    easyApply: config.easy_apply,
    employmentType: config.employment_type,
    experienceLevel: config.experience_levels,
    industryIds: config.industry_ids,
    jobTitles: config.job_titles,
    locations: config.locations,
    maxItems: config.max_items,
    under10Applicants: config.under_10_applicants,
    workplaceType: config.workplace_types
  };

  return {
    json: {
      ...f,
      search_name: config.search_name,
      country_filter: config.country_filter,
      apify_payload: payload,
      config_snapshot: config,
      execution_timestamp: new Date().toISOString()
    }
  };
});

const input = $json.data || $json;
const base = $('Build Direct Apify Payload').item.json;

return [{
  json: {
    ...base,
    actor_run_id: input.id,
    dataset_id: input.defaultDatasetId || '',
    run_status: input.status,
    started_at_actor: new Date().toISOString()
  }
}];

const statusBody = $json.data || $json;
const previous = (() => {
  try { return $('Track Poll Attempt').last().json; } catch { return $('Extract Run Metadata').first().json; }
})();

const pollAttempt = Number(previous.poll_attempt || 0) + 1;
const maxPollAttempts = Number($env.APIFY_MAX_POLL_ATTEMPTS || 30);
const terminalStatuses = new Set(['SUCCEEDED', 'FAILED', 'ABORTED', 'TIMED-OUT', 'TIMED_OUT']);
const status = String(statusBody.status || '').toUpperCase();
const timedOut = pollAttempt >= maxPollAttempts && !terminalStatuses.has(status);

return [{
  json: {
    ...previous,
    data: statusBody,
    run_status: timedOut ? 'POLL_TIMEOUT' : status,
    poll_attempt: pollAttempt,
    max_poll_attempts: maxPollAttempts,
    poll_timed_out: timedOut,
    actor_run_id: previous.actor_run_id || statusBody.id || '',
    dataset_id: previous.dataset_id || statusBody.defaultDatasetId || '',
    last_polled_at: new Date().toISOString()
  }
}];

const datasetItems = $input.all().map(i => i.json);
const parent = $('Extract Run Metadata').first().json;

return [{
  json: {
    ...parent,
    dataset_id: parent.dataset_id || $('Get Run Status').first().json.data.defaultDatasetId,
    execution_timestamp: new Date().toISOString(),
    jobs_raw: datasetItems,
    jobs_scraped: datasetItems.length
  }
}];

const input = $input.first().json;
const jobs = Array.isArray(input.jobs_raw) ? input.jobs_raw : [];

const pick = (...v) => v.find((x) => x !== undefined && x !== null && x !== '');
const arr = (v) => (Array.isArray(v) ? v : []);
const strArr = (v) =>
  arr(v).map((x) => (typeof x === 'string' ? x : JSON.stringify(x))).filter(Boolean);

const normalized = jobs.map((j) => {
  const linkedinUrlRaw = pick(j.linkedinUrl, j.jobUrl, j.link, j.url, '');
  const linkedinUrl = typeof linkedinUrlRaw === 'string' ? linkedinUrlRaw : String(linkedinUrlRaw || '');

  const inferredId =
    (linkedinUrl.match(/\/jobs\/view\/(\d+)/) || linkedinUrl.match(/currentJobId=(\d+)/) || [])[1] || '';

  const parsedLoc = j.location?.parsed || {};
  const company = j.company || {};

  return {
    run_id: input.run_id,
    started_at: input.started_at,
    actor_run_id: input.actor_run_id,
    dataset_id: input.dataset_id,
    search_name: input.search_name,
    country_filter: input.country_filter,

    job_id: pick(j.jobId, j.id, inferredId, ''),
    title: pick(j.title, j.jobTitle, ''),
    company_name: pick(j.companyName, company.name, ''),
    company_linkedin: pick(j.companyUrl, company.linkedinUrl, ''),
    company_website: pick(j.companyWebsite, company.website, ''),
    location_text: pick(j.locationText, j.location?.linkedinText, parsedLoc.text, ''),
    country: pick(j.countryCode, j.location?.countryCode, parsedLoc.countryCode, parsedLoc.country, ''),
    state: pick(parsedLoc.state, parsedLoc.regionCode, ''),
    city: pick(parsedLoc.city, ''),
    workplace_type: pick(j.workplaceType, ''),
    employment_type: pick(j.employmentType, ''),
    experience_level: pick(j.experienceLevel, ''),
    posted_date: pick(j.postedDate, j.postedAt, ''),
    expiry_date: pick(j.expireAt, j.expiryDate, ''),
    applicant_count: pick(j.applicantCount, j.applicationsCount, j.applicants, ''),
    job_url: linkedinUrl,
    easy_apply_url: pick(j.easyApplyUrl, j.applyUrl, ''),
    description: pick(j.descriptionText, j.description, ''),
    salary_text: pick(j.salary?.text, j.salaryText, ''),
    industries: strArr(j.industries),
    job_functions: strArr(j.jobFunctions),
    company_size: pick(company.employeeCount, company.employeeCountRange?.start, ''),
    company_followers: pick(company.followerCount, ''),
    apply_method_type: pick(j.applyMethod?.type, j.applyMethodType, ''),
    ats_system: pick(j.applicantTrackingSystem, j.atsSystem, ''),
    scraped_at: new Date().toISOString(),
    raw_json: j
  };
});

return normalized.map((json) => ({ json }));

const toCountryCode = (value) => {
  const v = String(value || '').trim().toUpperCase();
  const map = {
    INDIA: 'IN',
    IN: 'IN',
    US: 'US',
    USA: 'US',
    'UNITED STATES': 'US'
  };
  return map[v] || v;
};

return $input.all().map((item) => {
  const j = item.json;

  const targetCountry = toCountryCode(j.country_filter || $env.COUNTRY_FILTER_DEFAULT || 'IN');
  const sourceCountry = toCountryCode(j.country);

  const locText = String(j.location_text || '');
  const inFallback = /\b(india|bengaluru|bangalore|hyderabad|pune|gurgaon|noida|mumbai|delhi|chennai)\b/i.test(locText)
    ? 'IN'
    : sourceCountry;

  const effective = inFallback || sourceCountry;
  const accepted = effective === targetCountry;

  j.country = effective;
  j.filter_stage = 'country_filter';
  j.filter_reason = accepted ? 'accepted' : `country_mismatch:${effective}->${targetCountry}`;
  j.is_rejected = !accepted; // boolean, not string

  return { json: j };
});

const simpleHash = (s) => {
  let h = 0;
  for (let i = 0; i < s.length; i += 1) {
    h = ((h << 5) - h) + s.charCodeAt(i);
    h |= 0;
  }
  return String(Math.abs(h));
};

return $input.all().map((item) => {
  const j = item.json;
  const normalizedUrl = String(j.job_url || '').trim().toLowerCase();
  const composite = [
    String(j.title || '').trim().toLowerCase(),
    String(j.company_name || '').trim().toLowerCase(),
    String(j.location_text || '').trim().toLowerCase()
  ].join('|');

  j.dedupe_key_job_id = String(j.job_id || '').trim();
  j.dedupe_key_url = normalizedUrl;
  j.dedupe_key_hash = simpleHash(composite);
  j.jd_text_for_ai = String(j.description || '');
  j.processing_status = 'NEW';
  j.date_created = new Date().toISOString();
  return { json: j };
});

const currentJobId = String($json.job_id || '').trim();
const originals = $('Generate Dedupe Keys').all().map((item) => item.json);
const original = originals.find((job) => String(job.job_id || '').trim() === currentJobId) || $('Generate Dedupe Keys').item.json;

return [{
  json: {
    ...original,
    jobs_mastertracker_written: true
  }
}];

const MAX_CELL_CHARS = 49000;
const valueForSheet = (value) => {
  if (value === undefined || value === null) return '';
  if (typeof value === 'number' || typeof value === 'boolean') return value;
  const text = Array.isArray(value)
    ? value.map((v) => typeof v === 'object' ? JSON.stringify(v) : String(v)).join(', ')
    : typeof value === 'object'
      ? JSON.stringify(value)
      : String(value);
  return text.length <= MAX_CELL_CHARS ? text : text.slice(0, MAX_CELL_CHARS - 16) + '... [truncated]';
};
const pick = (source, keys) => Object.fromEntries(
  keys
    .filter((key) => source[key] !== undefined && source[key] !== null && source[key] !== '')
    .map((key) => [key, valueForSheet(source[key])])
);
const allowedKeys = [
  "dedupe_key_hash",
  "job_id",
  "job_url",
  "dedupe_key_job_id",
  "dedupe_key_url",
  "run_id",
  "search_name",
  "processing_status",
  "date_created"
];

return $input.all().map((item) => ({
  json: {
    ...pick(item.json, allowedKeys),
    hash: valueForSheet(item.json.dedupe_key_hash || item.json.dedupe_key_job_id || item.json.job_id || item.json.dedupe_key_url),
    cleaned_for_sheet: true
  },
  pairedItem: item.pairedItem
}));

const currentJobId = String($json.job_id || '').trim();
const currentHash = String($json.dedupe_key_hash || $json.hash || '').trim();
const originals = $('Generate Dedupe Keys').all().map((item) => item.json);
const original = originals.find((job) => String(job.job_id || '').trim() === currentJobId)
  || originals.find((job) => String(job.dedupe_key_hash || '').trim() === currentHash)
  || $('Generate Dedupe Keys').item.json;

return [{
  json: {
    ...original,
    processed_jobs_written: true
  }
}];

const resumeMaster = $env.RESUME_MASTER_PROFILE || 'Set RESUME_MASTER_PROFILE env var';
const minScore = Number($env.AI_MATCH_THRESHOLD || 70);

return $input.all().map((item) => {
  const j = item.json;
  const jdText = j.jd_text_for_ai || j.description || '';
  const prompt = [
    'You are a hiring-fit scoring engine. Output strict JSON only.',
    'Schema: {"match_score": number, "strengths": string[], "gaps": string[], "recommendation": string, "confidence": string}',
    'Minimum score gate is ' + minScore + '.',
    'Candidate profile:\n' + resumeMaster,
    'Job title: ' + (j.title || ''),
    'Company: ' + (j.company || j.company_name || ''),
    'Job description:\n' + jdText
  ].join('\n\n');

  j.ai_job_score_prompt = prompt;
  return { json: j };
});

const base = $('Build AI Scoring Prompt').item.json;
const minScoreRaw = Number($env.AI_MATCH_THRESHOLD || 70);
const minScore = Number.isFinite(minScoreRaw) ? minScoreRaw : 70;

const findScoreObject = (value, depth = 0) => {
  if (depth > 8 || value === undefined || value === null) return null;

  if (typeof value === 'string') {
    const text = value.trim();
    if (!text) return null;

    try { return findScoreObject(JSON.parse(text), depth + 1); } catch {}

    const firstBrace = text.indexOf('{');
    const lastBrace = text.lastIndexOf('}');
    if (firstBrace >= 0 && lastBrace >= 0) {
      try { return findScoreObject(JSON.parse(text.slice(firstBrace, lastBrace + 1)), depth + 1); } catch {}
    }

    return null;
  }

  if (Array.isArray(value)) {
    for (const child of value) {
      const found = findScoreObject(child, depth + 1);
      if (found) return found;
    }
    return null;
  }

  if (typeof value === 'object') {
    if (
      value.match_score !== undefined ||
      value.score !== undefined ||
      value.matchScore !== undefined ||
      value.fit_score !== undefined
    ) return value;

    for (const child of Object.values(value)) {
      const found = findScoreObject(child, depth + 1);
      if (found) return found;
    }
  }

  return null;
};

const parsed = findScoreObject($json) || {};
const scoreRaw = parsed.match_score ?? parsed.score ?? parsed.matchScore ?? parsed.fit_score ?? 0;
const aiMatchScore = Number(String(scoreRaw).replace(/[^0-9.-]/g, '')) || 0;
const passesThreshold = aiMatchScore >= minScore;

return [{
  json: {
    ...base,
    ai_match_score: aiMatchScore,
    ai_match_threshold: minScore,
    passes_threshold: passesThreshold,
    ai_score_parser_version: 'recursive_v2',
    ai_score_parse_debug: JSON.stringify({
      output_keys: Object.keys($json),
      raw_score: scoreRaw,
      parsed_found: Object.keys(parsed).length > 0
    }),
    ai_match_reason: JSON.stringify({
      strengths: parsed.strengths || [],
      gaps: parsed.gaps || [],
      recommendation: parsed.recommendation || ''
    }),
    ai_confidence: parsed.confidence || 'unknown'
  }
}];

const resumeLatex = $env.RESUME_LATEX_FULL || 'Set RESUME_LATEX_FULL env var';
const salutation = $env.COLDMAIL_SALUTATION || '[Name]';

return $input.all().map((item) => {
  const j = item.json;
  const jdText = j.jd_text_for_ai || j.description || '';
  j.resume_tweaks_prompt = [
    'Return strict JSON only.',
    'Schema: {"summary_tweaks":[],"experience_tweaks":[],"skills_to_add":[],"ats_keywords":[],"important_notes":[]}',
    'Company: ' + (j.company || j.company_name || ''),
    'Role: ' + (j.title || ''),
    'Job description:\n' + jdText,
    'Resume LaTeX:\n' + resumeLatex
  ].join('\n\n');

  j.coldmail_prompt = [
    'Write concise referral coldmail in plain text.',
    'Use salutation exactly as: ' + salutation,
    'Company: ' + (j.company || j.company_name || ''),
    'Role: ' + (j.title || ''),
    'Candidate highlights: ' + (j.ai_match_reason || '')
  ].join('\n\n');

  return { json: j };
});

const base = $('Build Resume+Coldmail Prompt').item.json;
const resumeRaw = $('Message a model - Resume Tweaks').item.json.text || '{}';
const coldmail = $('Message a model - Coldmail').item.json.text || '';

let resumeParsed;
try {
  const firstBrace = resumeRaw.indexOf('{');
  const lastBrace = resumeRaw.lastIndexOf('}');
  const jsonSlice = firstBrace >= 0 && lastBrace >= 0 ? resumeRaw.slice(firstBrace, lastBrace + 1) : '{}';
  resumeParsed = JSON.parse(jsonSlice);
} catch {
  resumeParsed = { summary_tweaks: [], experience_tweaks: [], skills_to_add: [], ats_keywords: [], important_notes: ['json_parse_error'] };
}

return [{
  json: {
    ...base,
    ai_resume_tweaks: JSON.stringify(resumeParsed),
    ai_coldmail: coldmail,
    processed_for_ai: true,
    processed_for_resume: true,
    processed_for_coldmail: true,
    summarization_cycle_id: `${new Date().toISOString().slice(0,10)}_${$execution.id}`
  }
}];

const base = $('Init Run').item.json;
const jobsScraped = (() => {
  try { return $('Prepare Output').item.json.jobs_scraped || 0; } catch { return 0; }
})();
const jobsAccepted = (() => {
  try { return $('Generate Dedupe Keys').all().length; } catch { return 0; }
})();
const highProcessed = (() => {
  try { return $('Update JobsMasterTracker AI Fields').all().length; } catch { return 0; }
})();
const lowProcessed = (() => {
  try { return $('Update Low Match Status').all().length; } catch { return 0; }
})();

return [{
  json: {
    run_id: base.run_id,
    started_at: base.started_at,
    completed_at: new Date().toISOString(),
    jobs_scraped: jobsScraped,
    jobs_filtered: jobsAccepted,
    jobs_added: jobsAccepted,
    jobs_rejected: Math.max(jobsScraped - jobsAccepted, 0),
    ai_processed: highProcessed + lowProcessed,
    failures: 0,
    notes: 'completed'
  }
}];
